 public bool JsonRpcRequest(ref object data,string method,string uri,string id){bool? handled=null;Props(ref data,method,uri,id,ref handled);if(handled.HasValue)return handled.Value;PickEdit(ref data,method,uri,id,ref handled);if(handled.HasValue)return handled.Value;Pick(ref data,method,uri,id,ref handled);if(handled.HasValue)return handled.Value;Detail(ref data,method,uri,id,ref handled);if(handled.HasValue)return handled.Value;F.Trace+="rpc:"+method+":"+F.T(uri)+":"+F.Dump(data)+":"+(UUID.TryParse(id,out UUID guid)&&!guid.IsZero()?1:0)+";";bool notes=data is UserProfileNotes;if(F.Mode==7)throw new Exception("rpc");if(F.Mode==1||F.Mode==2||F.Mode==10){if(notes){var n=(UserProfileNotes)data;n.TargetId=F.Id(3);n.Notes=F.Mode==10?null:F.Text;}else{var p=(UserPreferences)data;p.IMViaEmail=true;p.Visible=false;p.EMail=F.Mode==10?null:F.Text;}}if(F.Mode==3||F.Mode==4){if(notes)data=new UserProfileNotes{UserId=F.Id(2),TargetId=F.Id(4),Notes=F.Text};else data=new UserPreferences{UserId=F.Id(2),IMViaEmail=false,Visible=true,EMail=F.Text};}if(F.Mode==5||F.Mode==9)data=null;if(F.Mode==6)data=notes?(object)new UserPreferences():new UserProfileNotes();return F.Mode!=0&&F.Mode!=2&&F.Mode!=4&&F.Mode!=9;}}
