static class F{
 public static int Mode,Flags;public static string Uri,Text,Trace,AssetUri;
 public static UUID Id(int n)=>new UUID("00000000-0000-0000-0000-"+n.ToString("x12"));
 public static void Fail(int f,string message){if((Flags&f)!=0)throw new Exception(message);}
 public static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();public static string T(string s){if(s==null)return "-";var b=new byte[s.Length*2];for(int i=0;i<s.Length;i++){b[2*i]=(byte)s[i];b[2*i+1]=(byte)(s[i]>>8);}return Convert.ToHexString(b).ToLowerInvariant();}
 static string Decode(string s){if(s=="-")return null;if(s==".")return "";var b=Convert.FromHexString(s);var c=new char[b.Length/2];for(int i=0;i<c.Length;i++)c[i]=(char)(b[i*2]|b[i*2+1]<<8);return new string(c);}
