 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var a=line.Split(' ');int op=int.Parse(a[0]);Mode=int.Parse(a[1]);Flags=int.Parse(a[2]);Uri=Decode(a[3]);string arg=Decode(a[4]);Text=Decode(a[5]);Trace="";string result="OK";try{var module=new Original();IClientAPI client=(Flags&1)!=0?null:new Client();UUID.TryParse(arg,out UUID target);switch(op){case 0:List<string> args=(Flags&4)!=0?null:(Flags&8)!=0?new List<string>():new List<string>{arg};module.NotesRequest((Flags&2)!=0?new object():client,"ignored",args);break;case 1:module.NotesUpdate(client,target,Text);break;case 2:module.UserPreferencesRequest(client);break;case 3:module.UpdateUserPreferences((Flags&2097152)!=0,(Flags&8388608)!=0,client);break;case 4:result=module.Route(target);break;case 5:result=module.Presence(target);break;}}catch(Exception e){result="EX:"+H(e.Message);}Console.WriteLine(result+"|"+H(Trace));}}
